CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_RUN_NIGHTLY_ETL()
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
CALL DW.SP_LOAD_DIM_STORE();
CALL DW.SP_LOAD_DIM_PRODUCT();
CALL DW.SP_LOAD_DIM_DATE();
CALL DW.SP_LOAD_FACT_SALES();
CALL DW.SP_LOAD_FACT_INVENTORY();
CALL DW.SP_REFRESH_AGGREGATES();
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_BATCH_CONTROLLER()
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
UPDATE DW.ETL_BATCH SET status = 'RUNNING', started_at = CURRENT_TIMESTAMP() WHERE BATCH_ID = (SELECT MAX(BATCH_ID) FROM DW.ETL_BATCH);
CALL DW.SP_RUN_NIGHTLY_ETL();
CALL DW.SP_VALIDATE_DATA('FACT_SALES');
UPDATE DW.ETL_BATCH SET status = 'COMPLETED', finished_at = CURRENT_TIMESTAMP() WHERE BATCH_ID = (SELECT MAX(BATCH_ID) FROM DW.ETL_BATCH WHERE status = 'RUNNING');
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_ARCHIVE_OLD_DATA("CUTOFF_DATE" DATE)
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
INSERT INTO ARCHIVE.FACT_SALES_HIST
SELECT * FROM DW.FACT_SALES f
JOIN DW.DIM_DATE d ON f.date_key = d.date_key
WHERE d.day_date < :cutoff_date;

DELETE FROM DW.FACT_SALES
WHERE date_key IN (
  SELECT date_key FROM DW.DIM_DATE WHERE day_date < :cutoff_date
);

CALL DW.SP_LOG_ETL_STATUS('Archive completed for dates before ' || :cutoff_date);
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_WEEKLY_RESTOCK_SYNC()
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
CALL DW.SP_LOAD_FACT_INVENTORY('WEEKLY');
CALL DW.SP_REFRESH_AGGREGATES();
CALL DW.SP_LOG_ETL_STATUS('Weekly restock sync done');
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW_DEV.SP_FIX_COGS_JUNK_DEV()
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
UPDATE DW_DEV.FACT_SALES_BAK SET unit_cost = 0 WHERE unit_cost IS NULL;
DELETE FROM DW_DEV.JUNK_TEMP WHERE created_at < '2022-01-01';
$$;

CREATE OR REPLACE PROCEDURE LAB_DB.DW.SP_FULL_REFRESH_DAILY()
RETURNS STRING
LANGUAGE SQL
EXECUTE AS CALLER
AS $$
CALL DW.SP_RUN_NIGHTLY_ETL();
CALL DW.SP_LOAD_PROMOTIONS();
CALL DW.SP_LOAD_RETURNS('DAILY');
CALL DW.SP_ARCHIVE_OLD_DATA(DATEADD(YEAR, -3, CURRENT_DATE()));
$$;

CREATE TABLE LAB_DB.DW.ETL_LOG (
  log_id INT AUTOINCREMENT,
  log_message VARCHAR(1000),
  log_timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP(),
  log_level VARCHAR(20)
);

CREATE TABLE LAB_DB.DW.LKP_REGION (
  region_id INT PRIMARY KEY,
  region_name VARCHAR(100),
  region_code VARCHAR(10)
);

CREATE TABLE LAB_DB.DW_DEV.JUNK_TEMP_DATA (
  id INT,
  payload VARCHAR(4000),
  created_at TIMESTAMP
);
